/* Balanced four-work previews; preserve the original artwork ratios. */
.collection-collage{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(2,minmax(0,1fr));gap:6px;padding:6px;background:#e7e7e2;aspect-ratio:1.72}
.collage-tile{min-width:0;min-height:0;overflow:hidden;background:#f3f3f0;display:flex;align-items:center;justify-content:center}
.collection-collage .collage-tile img{width:100%;height:100%;object-fit:contain;padding:0;transform:none}
.card-on-k.collection-collage .collage-tile img{padding:5px}
.footer-contact{margin:0}
@media(max-width:700px){.collection-collage{gap:4px;padding:4px}}

/* On.K overview pairs the brand moodboard with the complete Instagram feed. */
.card-on-k.onk-overview{grid-template-columns:1.25fr 1fr;grid-template-rows:minmax(0,1fr);gap:10px;padding:12px;background:#eeeee9}
.card-on-k.onk-overview .collage-tile{background:#f8f8f6}
.card-on-k.onk-overview .collage-tile img{object-fit:contain;padding:0;width:100%;height:100%}
@media(max-width:700px){.card-on-k.onk-overview{gap:6px;padding:8px}}

/* Category views expose the work itself without a second navigation step. */
[hidden]{display:none!important}
.work-panel{min-width:0}
.inline-collection .collection-heading{padding:8px 0 34px;max-width:100%}
.inline-collection .collection-meta{margin:0 0 12px;font-size:13px}
.inline-collection .collection-heading h3{font-size:clamp(1.7rem,2.5vw,2.3rem);line-height:1.5;font-weight:700;margin:0 0 12px}
.inline-collection .case-grid{padding:0 0 42px}
.inline-collection .case h4{font-size:22px;line-height:1.6;font-weight:650;margin:9px 0 12px}
.inline-collection .strategy-section,.inline-collection .impact-section{margin:0}
.inline-collection .strategy-intro h4{font-size:25px;line-height:1.65;margin:14px 0 16px}
.inline-collection .impact-section .section-head h4{font-size:28px;line-height:1.5;margin:0}
.inline-collection .impact-grid h5{font-size:18px;margin:15px 0 5px;line-height:1.65}
.inline-collection .collection-note{padding:0;margin-bottom:0}
.copy-sections{display:flex;flex-wrap:wrap;gap:12px 28px;padding:0 0 24px;margin:0 0 28px;border-bottom:1px solid var(--line);font-size:14px}
.copy-sections a{border-bottom:1px solid var(--line);padding-bottom:3px}
.copy-collection{scroll-margin-top:30px}
.copy-collection+.copy-collection{border-top:1px solid var(--line);margin-top:44px;padding-top:36px}
@media(max-width:700px){.inline-collection .collection-heading{padding:4px 0 26px}.inline-collection .collection-heading h3{font-size:27px}.inline-collection .case h4{font-size:21px}.inline-collection .case-grid{padding:0 0 30px}.inline-collection .strategy-intro h4{font-size:23px}.inline-collection .impact-section .section-head h4{font-size:25px}.inline-collection .impact-grid h5{font-size:15px}.filters{gap:18px;flex-wrap:wrap}.copy-sections{gap:12px 24px}.copy-collection+.copy-collection{margin-top:32px;padding-top:28px}}

/* K-Pick Map thumbnails open the corresponding Instagram reels. */
.impact-grid .reel-link{display:block;aspect-ratio:1.2;overflow:hidden;background:#eee;cursor:pointer}
.impact-grid .reel-link img{transition:opacity .2s}
.impact-grid .reel-link:hover img{opacity:.88}
@media(max-width:700px){.impact-grid .reel-link{aspect-ratio:.9}}
